# shapes: (bar_row, bar_col_center, stem_dir, stem_len, tip_row, tip_col, bbox)
shapes = [
 dict(name='A', bar=(2,3), dir='up',   ln=1, tip=(1,3)),
 dict(name='B', bar=(4,8), dir='down', ln=2, tip=(6,8)),
 dict(name='C', bar=(5,1), dir='down', ln=1, tip=(6,1)),
 dict(name='D', bar=(8,6), dir='down', ln=1, tip=(9,6)),
 dict(name='E', bar=(10,2),dir='up',   ln=1, tip=(9,2)),
