]
out_cells = {(0,0):3,(0,2):3,(2,0):3,(0,3):1,(0,5):1,(2,3):1,(2,5):1}
up = {s['name'] for s in shapes if s['dir']=='up'}
print('up count', len(up), 'down count', 7-len(up))

# brute force: for each shape pick an anchor (bar or tip) and try quantizations
anchors = {s['name']: [(s['bar']), (s['tip'])] for s in shapes}
names = [s['name'] for s in shapes]
color = {n:(3 if n in up else 1) for n in names}
sols=[]
for acombo in itertools.product(*[range(2) for _ in names]):
    pts = {n: anchors[n][i] for n,i in zip(names, acombo)}
    # try row maps: r->a*r+b quantized; search a,b over small rationals with floor/round
    for a in [1/2,1/3,2/5,3/10,1/5,2/7,3/7,1/4,2/3]:
        for b in [0,1,2,3,-1,-2]:
            for c in [1/2,1/3,2/5,3/10,1/5,2/7,3/7,1/4,2/3]:
                for d in [0,1,2,3,-1,-2]:
                    for f in (math.floor, round):
                        m={}
                        ok=True
                        for n in names:
                            r,c_=pts[n]
                            cell=(f(r*a+b), f(c_*c+d))
                            if cell not in out_cells or out_cells[cell]!=color[n]:
                                ok=False; break
                            if cell in m: ok=False; break
                            m[cell]=n
                        if ok and len(m)==7:
                            sols.append((acombo,a,b,c,d,f.__name__,m))
print(len(sols))
